@layer components {
  .button {
    padding: 0.5rem 1rem;
  }
}

/* 仍然是同一个 components 层 */
@layer components {
  .card {
    padding: 1rem;
  }
}

@layer framework {
  @layer reset {
    button {
      appearance: none;
    }
  }

  @layer components {
    .button {
      padding: 0.5rem 1rem;
    }
  }
}

@layer components {
  .button {
    color: blue;
  }
}

@layer reset {
  button {
    color: green;
  }
}

@layer utilities {
  .text-red {
    color: red;
  }
}

/* 优先级和第一次声明的顺序有关
   后续声明的同名 layer 不会修改 layer 的优先级 */
@layer components {
  .text-pink {
    color: pink;
  }
}

.button {
  color: black;
}

@layer components {
  #app .page .button {
    color: blue;
  }
}

@layer utilities {
  .button {
    color: red;
  }
}

@layer framework, application;

@layer framework {
  @layer reset, components;

  @layer reset {
    .button {
      color: gray;
    }
  }

  @layer components {
    .button {
      color: blue;
    }
  }
}

@layer application {
  @layer base, utilities;

  @layer base {
    .button {
      color: green;
    }
  }

  @layer utilities {
    .button {
      color: red;
    }
  }
}

/* Shadow DOM 内部 */
:host {
  color: blue;
}

/* 外部页面 */
x-button {
  color: red;
}

:fullscreen:not(:root) {
  position: fixed !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  min-width: 0 !important;
  max-width: none !important;
  min-height: 0 !important;
  max-height: none !important;
  box-sizing: border-box !important;
  transform: none !important;
}

/* Shadow DOM 内部 */
:host {
  color: blue !important;
}

/* 外部页面 */
x-button {
  color: red !important;
}

@layer reset, components, utilities;

@layer reset {
  .button {
    color: red !important;
  }
}

@layer utilities {
  #app .page .button {
    color: blue !important;
  }
}

@layer reset {
  button {
    color: black;
  }
}

@layer base {
  button {
    font-family: system-ui;
  }
}

@layer components {
  .button {
    color: white;
    background: royalblue;
  }
}

@layer utilities {
  .text-red {
    color: red;
  }

  .restore-component-color {
    color: revert-layer;
  }
}

@layer reset, base, components, utilities;

@layer reset {
  .button {
    color: black;
  }
}

@layer base {
  /* 没有设置 color */
}

@layer components {
  /* 没有匹配 .button 的 color */
}

@layer utilities {
  .button {
    color: revert-layer;
  }
}

@layer framework, application;

@layer framework {
  .target {
    color: blue;
  }
}

@layer application {
  @layer base, components;

  @layer base {
    .target {
      color: revert-layer;
    }
  }
}

@layer important-overrides, vendor, application;

@layer important-overrides {
  .btn {
    color: red !important;
  }
}
